//! One Root-serialized actual-service composition. Engine loading/entry facts
//! are injected; production native cold/retained entry is a separate fixture.
use super::*;
use nt2_desktop_g0::{startup_local as startup,startup_pending,waiting_local,protocol_waiting};
#[derive(Clone,Default)]struct Store{inner:MemoryStore,fail_proof:Arc<std::sync::atomic::AtomicBool>,failures:Arc<AtomicU64>}
impl CredentialStore for Store{
 fn save(&self,p:&ServiceProfile,b:&SecretBlob)->Result<(),crate::secrets::StoreError>{if b.bytes().windows(9).any(|x|x==b"\"proof\":\"")&&self.fail_proof.swap(false,Ordering::AcqRel){self.failures.fetch_add(1,Ordering::AcqRel);return Err(crate::secrets::StoreError::Unavailable)}self.inner.save(p,b)}
 fn load(&self,p:&ServiceProfile)->Result<Option<SecretBlob>,crate::secrets::StoreError>{self.inner.load(p)}fn delete(&self,p:&ServiceProfile)->Result<(),crate::secrets::StoreError>{self.inner.delete(p)}
}
fn fresh(store:Store,device:uuid::Uuid,root:std::path::PathBuf,http:reqwest::Client)->Core<Store>{let mut c=Core::new(store,device,Arc::new(Mutex::new(None)),root);c.http=http;c.open_browser=false;std::fs::create_dir_all(&c.claims_root).unwrap();c.enable_g3(&c.claims_root.join("journal.jsonl"),Arc::new(Mutex::new(nt2_desktop_g0::g3_runtime::Exchange::default()))).unwrap();c}
fn configure(c:&mut Core<Store>){c.request_social(Arc::new(Mutex::new(nt2_desktop_g0::g3_social_stream::Exchange::default()))).unwrap();c.social_profile=Some(nt2_desktop_g0::g3_social_installation::development_profile().unwrap()["profile"].clone());c.configure_game(&std::env::var("NT2_FLOW_GAME_FIXTURE").unwrap()).unwrap();*c.expected_game.lock().unwrap()=Some(crate::pipe::verified_process_path(&std::env::current_exe().unwrap()).unwrap());}
async fn prepared(c:&mut Core<Store>,origin:&str)->(startup::WaitingMarker,wire::Request){
 c.select(origin,"",false).await.unwrap();registered_as(c,"alex").await;configure(c);c.enable_automatic_setup();c.create_fixture(false).await.unwrap();assert!(!c.view()["native_armed"].as_bool().unwrap());
 let until=Instant::now()+Duration::from_secs(15);loop{c.poll_startup_stage().await;if c.pending.lock().unwrap().as_ref().is_some_and(|p|p.startup_ready){break}assert!(Instant::now()<until,"pending-before-readiness failed: {:?}",c.native_failure);tokio::time::sleep(Duration::from_millis(50)).await;}
 let b=c.pending.lock().unwrap().as_ref().unwrap().startup_bundle.clone().unwrap();let adapter=super::super::rejoin::ResumeStore(c.store.clone());assert!(startup_pending::load(&adapter,b.scope(),b.world()).unwrap().unwrap().ready());
 // Same production off-lock transaction as pipe; PID birth and engine callback
 // are injected here. The separate real-native fixture verifies actual OS ABI.
 let lane=crate::pipe::startup::Lane::new(c.pending.clone());let mut request=vec![0;32];request[..4].copy_from_slice(&crate::handoff::MAGIC.to_le_bytes());request[4..8].copy_from_slice(&9u32.to_le_bytes());request[8..12].copy_from_slice(&16u32.to_le_bytes());request[16..32].copy_from_slice(b.world().as_bytes());
 loop{let reply=lane.handle(nt2_local_ws::owner::Id::OsProcess(std::process::id()),&request,Duration::ZERO);if reply[12]==1{break}assert_eq!(reply[12],2);assert!(Instant::now()<until);tokio::time::sleep(Duration::from_millis(5)).await;}drop(lane);facts(c,1,true);
 let mut attach=c.request(false);attach.game_attach=Some(wire::GameAttach{game_instance_id:Some(uuid::Uuid::new_v4().to_string()),game_version:Some("Noita-Jan25-2025".into()),mod_version:Some(nt2_desktop_g0::g3_social_installation::MOD_VERSION.into()),bridge_version:Some(nt2_desktop_g0::g3_social_installation::BRIDGE_VERSION.into()),capabilities:Some(c.local_game_capabilities()),preparation_id:Some(b.scope().preparation.clone())});let retry=Retry{request:attach.clone(),until:Instant::now()+Duration::from_secs(30)};
 loop{let p=c.pending.lock().unwrap().clone().unwrap();if c.seal_startup_attach(&p,&retry).await.unwrap(){break}assert!(Instant::now()<until);tokio::time::sleep(Duration::from_millis(5)).await;}
 let marker=startup::WaitingMarker::decode(&c.native_diagnostics.lock().unwrap().rejoin.metadata.as_ref().unwrap().2).unwrap();assert_eq!(marker.kind,"nt2-pending");assert_eq!(marker.local_world,b.world());let retained=startup_pending::load(&adapter,b.scope(),b.world()).unwrap().unwrap();assert_eq!(retained.attach.as_ref().unwrap().request.request_id,attach.request_id);assert!(c.game.is_none());(marker,attach)
}
async fn cold(mut c:Core<Store>,fixture:&mut Fixture,marker:&startup::WaitingMarker,root:std::path::PathBuf)->Core<Store>{
 let store=c.store.as_ref().clone();let desktop=c.desktop.take();let room=c.room.take();let device=c.device;let http=c.http.clone();drop(c);fixture.command("advance:40000");let mut c=fresh(store,device,root,http);c.select(&fixture.origin,"",false).await.unwrap();c.desktop=desktop;c.rotate().await.unwrap();c.room=room;configure(&mut c);
 c.native_diagnostics.lock().unwrap().rejoin.waiting_offered=Some((nt2_local_ws::owner::Id::OsProcess(std::process::id()),marker.clone()));c.native_diagnostics.lock().unwrap().rejoin.contact=Some(crate::pipe::rejoin::Contact{pid:nt2_local_ws::owner::Id::OsProcess(std::process::id()),context:[8;16],association:*marker.local_world.as_bytes(),actual:marker.actual_seed.parse().unwrap()});
 let until=Instant::now()+Duration::from_secs(18);let mut last=None;while c.game.is_none(){assert!(Instant::now()<until,"cold pending/waiting recovery: {last:?}");if c.pending.lock().unwrap().is_some(){facts(&mut c,1,true)}if let Err(e)=c.waiting_tick().await{last=Some(e)}assert!(c.pending.lock().unwrap().as_ref().is_none_or(|p|!p.release));tokio::time::sleep(Duration::from_millis(50)).await;}
 assert!(c.preparation.is_none());assert_eq!(c.waiting_local_world(),Some(marker.local_world));assert_eq!(c.pending.lock().unwrap().as_ref().unwrap().actual_seed.map(|v|v.to_string()),Some(marker.actual_seed.clone()));assert!(!c.pending.lock().unwrap().as_ref().unwrap().release);c
}
async fn offline_drain(c:&mut Core<Store>,scope:&startup::Scope,marker:&startup::WaitingMarker){
 let selector=waiting_local::load_saved_selector(&super::super::rejoin::ResumeStore(c.store.clone()),scope,marker).unwrap().unwrap().marker.clone();c.continue_offline().unwrap();let until=Instant::now()+Duration::from_secs(12);
 loop{let _=c.waiting_tick().await;let j=waiting_local::load_retired(&super::super::rejoin::ResumeStore(c.store.clone()),scope,&selector).unwrap().unwrap();if j.retirement_done{break}assert!(Instant::now()<until,"promoted pending offline queue: {:?}",c.waiting_retirement.error);tokio::time::sleep(Duration::from_millis(50)).await;}
}
async fn entered(c:&mut Core<Store>,health:&mut health::HealthRunner<Store>,marker:&startup::WaitingMarker){
 for n in 2..=6{facts(c,n,n==2);let result=health.pump().await;c.sync_health();if n==2{assert!(c.pending.lock().unwrap().as_ref().unwrap().release,"selected after-Start canonical admission failed: {result:?}")}tokio::time::sleep(Duration::from_millis(2050)).await;}
 let a=c.resume_intent.association().expect("Selected original admission must promote through the existing owner");assert_eq!(a.local_world,marker.local_world);assert_eq!(a.actual_seed,marker.actual_seed);assert!(!a.original_start.is_empty());assert!(c.game.as_ref().unwrap().entered);
}
#[test]#[ignore="Root must serialize the one disposable startup-repair consumer/service composition"]
fn startup_repair_actual_pending_loss_selected_start_and_offline(){tauri::async_runtime::block_on(async{
 let mut fixture=Fixture::start_script("spikes/noita-entry/.build/g3-startup-repair-client-20261017-01/fixture.mjs");let ca=reqwest::Certificate::from_pem(&std::fs::read(&fixture.ca).unwrap()).unwrap();let http=reqwest::Client::builder().use_native_tls().tls_certs_only(vec![ca]).no_proxy().redirect(reqwest::redirect::Policy::none()).timeout(Duration::from_secs(3)).build().unwrap();let root=std::env::temp_dir().join(format!("nt2-startup-compose-{}",uuid::Uuid::new_v4()));let mut cases=vec![];
 for cut in ["before-attach","attach-reply-discarded","enroll-proof-unpublished","direct-waiting-after-start-offline","enroll-proof-unpublished-after-start"]{
  let store=Store::default();let mut c=fresh(store.clone(),uuid::Uuid::new_v4(),root.join(cut).join("first"),http.clone());let (marker,attach)=prepared(&mut c,&fixture.origin).await;let original_preparation=c.preparation.as_ref().unwrap().preparation_id.clone();
  if cut=="attach-reply-discarded"{let url=format!("{}/v1/rpc",fixture.origin);let response=c.http.post(&url).bearer_auth(c.desktop.as_ref().unwrap().access.as_str()).header("content-type","application/json").body(serde_json::to_vec(&attach).unwrap()).send().await.unwrap();assert!(response.status().is_success());drop(response);assert!(c.game.is_none(),"Discarded reply must not reveal attachment/credentials to Client");
   let b=c.pending.lock().unwrap().as_ref().unwrap().startup_bundle.clone().unwrap();let r=startup_pending::load(&super::super::rejoin::ResumeStore(c.store.clone()),b.scope(),b.world()).unwrap().unwrap();let query=protocol_waiting::wire::Request{major:Some(1),revision:Some(protocol_waiting::REVISION.into()),service_id:Some(c.service.clone()),service_epoch:Some(c.epoch.clone()),session_epoch:Some(c.desktop.as_ref().unwrap().epoch.clone()),request_id:Some(uuid::Uuid::new_v4().to_string()),pending_outcome:Some(r.attach.as_ref().unwrap().original.clone()),..Default::default()};let response=super::super::waiting::rpc(&c.http,b.scope(),c.desktop.as_ref().unwrap(),&query).await.unwrap();let outcome=response.pending_outcome.unwrap();assert_eq!(outcome.original_outcome.as_deref(),Some("committed"));assert_eq!(outcome.coverage.as_deref(),Some("exact_consumed_attach_record"));assert!(outcome.effect_id.is_some());assert!(response.credentials.is_none()&&response.pending_proof.is_none());
  }
  if cut.starts_with("enroll-proof-unpublished"){
   c.attach_retry=Some(Retry{request:attach,until:Instant::now()+Duration::from_secs(30)});c.game_tick().await.unwrap();assert!(c.game.is_some());store.fail_proof.store(true,Ordering::Release);let mut health=c.health_runner();let until=Instant::now()+Duration::from_secs(16);let mut n=1;
   while store.failures.load(Ordering::Acquire)==0{assert!(Instant::now()<until,"Enrollment proof commit cut was not reached");n+=1;facts(&mut c,n,true);let _=health.pump().await;c.sync_health();assert!(!c.pending.lock().unwrap().as_ref().unwrap().release);tokio::time::sleep(Duration::from_millis(100)).await;}assert!(c.waiting_startup_marker().is_none());drop(health);
   if cut.ends_with("after-start"){c.collect_inspection().await.unwrap();c.final_start(vec![c.desktop.as_ref().unwrap().id.clone()],vec![]).await.unwrap();}
  }
  let mut c=cold(c,&mut fixture,&marker,root.join(cut).join("cold")).await;let scope=startup::recall(&super::super::rejoin::ResumeStore(c.store.clone()),&c.base,&c.service,&c.desktop.as_ref().unwrap().account,c.device,&marker).unwrap().unwrap().original;assert_eq!(Some(scope.preparation.clone()),original_preparation);
  if cut=="enroll-proof-unpublished-after-start"{
   let adapter=super::super::rejoin::ResumeStore(c.store.clone());let j=waiting_local::load_saved_selector(&adapter,&scope,&marker).unwrap().unwrap();assert!(j.intent.is_some()&&j.proof.is_none()&&!j.ready(),"Post-Start must not invent waiting proof");let original=startup_pending::load(&adapter,&scope,marker.local_world).unwrap().unwrap();c=cold(c,&mut fixture,&marker,root.join(cut).join("second-quit-before-entry")).await;let adapter=super::super::rejoin::ResumeStore(c.store.clone());let current=startup_pending::load(&adapter,&scope,marker.local_world).unwrap().unwrap();assert!(original.proof==current.proof,"Retained pending proof changed across repeated early quits");
  }
  let mut health=c.health_runner();facts(&mut c,1,true);let _=health.pump().await;c.sync_health();if cut!="enroll-proof-unpublished-after-start"{assert!(!c.pending.lock().unwrap().as_ref().unwrap().release);}
  if matches!(cut,"before-attach"|"direct-waiting-after-start-offline"){
   c.collect_inspection().await.unwrap();c.final_start(vec![c.desktop.as_ref().unwrap().id.clone()],vec![]).await.unwrap();drop(health);let mut c=cold(c,&mut fixture,&marker,root.join(cut).join("after-start")).await;let mut health=c.health_runner();
   if cut=="direct-waiting-after-start-offline"{facts(&mut c,2,true);let _=health.pump().await;c.sync_health();assert!(c.pending.lock().unwrap().as_ref().unwrap().release);drop(health);offline_drain(&mut c,&scope,&marker).await;}else{entered(&mut c,&mut health,&marker).await;drop(health);}drop(c);
  }else if cut=="enroll-proof-unpublished-after-start"{
   entered(&mut c,&mut health,&marker).await;drop(health);drop(c);
  }else{
   drop(health);offline_drain(&mut c,&scope,&marker).await;drop(c)
  }cases.push(json!({"cut":cut,"sameOriginalPreparation":true,"sameWorldSeedLoot":true,"heldBeforeCanonicalAdmission":true}));
 }
 let mut c=fresh(Store::default(),uuid::Uuid::new_v4(),root.join("offline"),http);let (marker,_)=prepared(&mut c,&fixture.origin).await;let scope=c.pending.lock().unwrap().as_ref().unwrap().startup_bundle.as_ref().unwrap().scope().clone();c.continue_offline().unwrap();let until=Instant::now()+Duration::from_secs(12);loop{let _=c.waiting_tick().await;let adapter=super::super::rejoin::ResumeStore(c.store.clone());let j=waiting_local::load_retired(&adapter,&scope,&marker).unwrap().unwrap();if j.retirement_done{break}assert!(Instant::now()<until,"pending offline canonical queue: {:?}",c.waiting_retirement.error);tokio::time::sleep(Duration::from_millis(50)).await;}
 assert!(startup::recall(&super::super::rejoin::ResumeStore(c.store.clone()),&scope.origin,&scope.service,&scope.account,scope.device,&marker).unwrap().is_none());fixture.command("peer-check");drop(c);
 let receipt=json!({"cases":cases,"pendingBeforeNativeReadiness":true,"exactAttachSealedBeforeSend":true,"opaqueAttachReplyDiscarded":true,"selectedOriginalAfterStart":true,"pendingOfflineCanonicalQueue":true,"peerUnaffected":true,"engineFactsInjected":true,"actualNoita":false,"canonicalRevision":protocol_waiting::REVISION});std::fs::write(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../spikes/noita-entry/.build/g3-startup-repair-client-20261017-01/composition.json"),serde_json::to_vec_pretty(&receipt).unwrap()).unwrap();assert!(root.canonicalize().unwrap().starts_with(std::env::temp_dir().canonicalize().unwrap()));std::fs::remove_dir_all(root).unwrap();
});}
